-- Optional demo catalog matching lib/demo-data.ts IDs.
-- Run after schema.sql if you want the included checkout API to work immediately against Supabase.
on conflict(id) do update set
  slug=excluded.slug,name=excluded.name,price=excluded.price,compare_at=excluded.compare_at,category=excluded.category,size=excluded.size,condition=excluded.condition,
  brand=excluded.brand,measurements=excluded.measurements,description=excluded.description,images=excluded.images,one_of_one=excluded.one_of_one,
  new_arrival=excluded.new_arrival,vintage_find=excluded.vintage_find,featured=excluded.featured;
